// Una riga per app: la pagina dei prezzi è il campo «prezzi» se c'è, altrimenti <sito>/pricing per le app a pagamento e la home per quelle gratis
const d = $input.first().json;
const out = [];
for (const g of d.gruppi || []) for (const a of g.app || []) {
  const base = String(a.url || '').replace(/\/$/, '');
  out.push({ json: { nome: a.nome, gruppo: g.nome, sito: a.url, pagina: a.prezzi || (a.prezzo === 'free' || a.prezzo === 'byok' || /github\.com|pricing|\/ai$/.test(base) ? base : `${base}/pricing`), scritto: a.limiti || '' } });
}
return out;

// Tiene solo le frasi che parlano di prezzi e piani gratis, ne fa un'impronta e la confronta con quella del mese prima.
// La prima volta salva le impronte senza mandare mail. La memoria resta solo quando il flusso è ATTIVO.
const memoria = $getWorkflowStaticData('global');
const prima = memoria.impronte || null;
const app = $('Una riga per app').all();
const pagine = $input.all();
const impronta = (s) => { let h = 5381; for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0; return h.toString(36); };
const nuove = {}, cambiate = [], irraggiungibili = [];
app.forEach((it, i) => {
  const a = it.json;
  const html = String(pagine[i]?.json?.testo || '');
  if (!html || pagine[i]?.json?.error) { irraggiungibili.push(a); if (prima?.[a.nome]) nuove[a.nome] = prima[a.nome]; return; }
  const testo = html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, '\n').replace(/&nbsp;|&#160;/g, ' ').replace(/&amp;/g, '&');
  const frasi = testo.split(/\n+/).map((r) => r.replace(/\s+/g, ' ').trim()).filter((r) => r.length > 2 && r.length < 200 && /([$€£]\s?\d|\d\s?[$€£]|\bfree\b|\/\s?mo\b|per month|\/month|credits?\b|requests?\b|tokens?\b|trial)/i.test(r));
  const k = impronta([...new Set(frasi)].sort().join('|'));
  nuove[a.nome] = k;
  if (prima && prima[a.nome] && prima[a.nome] !== k) cambiate.push({ ...a, frasi: [...new Set(frasi)].slice(0, 12) });
});
memoria.impronte = nuove;
if (!prima || (!cambiate.length && !irraggiungibili.length)) return [];
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const html = `${cambiate.length ? `<p><b>Pagine dei prezzi cambiate dal mese scorso</b> (da ricontrollare a mano):</p><ul>${cambiate.map((a) => `<li><a href="${esc(a.pagina)}">${esc(a.nome)}</a> (${esc(a.gruppo)}). Sul sito scriviamo: «${esc(a.scritto)}»<br><small>${a.frasi.map(esc).join(' · ')}</small></li>`).join('')}</ul>` : ''}${irraggiungibili.length ? `<p><b>Pagine che non si aprono</b> (forse hanno cambiato indirizzo):</p><ul>${irraggiungibili.map((a) => `<li><a href="${esc(a.pagina)}">${esc(a.nome)}</a></li>`).join('')}</ul>` : ''}<p>Per correggere la pagina <a href="https://freellmarena.com/apps">AI apps</a>, scrivi a Claude «aggiorna i prezzi delle app» con questo elenco.</p>`;
return [{ json: { oggetto: `FreeLLMArena: prezzi app, ${cambiate.length} cambiat${cambiate.length === 1 ? 'a' : 'e'}`, html } }];
